import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"Engineering Principles","description":"The working principles behind every project Reza Bazdar ships: run it, own it, secure it, document it, improve it.","frontmatter":{"title":"Engineering Principles","description":"The working principles behind every project Reza Bazdar ships: run it, own it, secure it, document it, improve it."},"headers":[],"relativePath":"en/about/principles/index.md","filePath":"en/about/principles/index.md"}`),a={name:`en/about/principles/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="engineering-principles" tabindex="-1">Engineering Principles <a class="header-anchor" href="#engineering-principles" aria-label="Permalink to “Engineering Principles”">​</a></h1><p>Principles are cheap to write and expensive to keep. These are the ones I actually keep — the same ones I audit agent-written code against before anything ships.</p><h2 id="_1-it-must-run" tabindex="-1">1. It must run <a class="header-anchor" href="#_1-it-must-run" aria-label="Permalink to “1. It must run”">​</a></h2><p>A project that compiles but does not run is a sketch, not software. Every repository I publish comes with a working entry point, real configuration and a deployment path. <a href="/Usf/en/projects/glm-free-api/">GLM Free API</a> is one Go file that serves real traffic; <a href="/Usf/en/projects/netpilot/">NetPilot</a> is a single binary you can execute in seconds. &quot;Works on my machine&quot; is where I start, not where I stop.</p><h2 id="_2-own-the-whole-stack" tabindex="-1">2. Own the whole stack <a class="header-anchor" href="#_2-own-the-whole-stack" aria-label="Permalink to “2. Own the whole stack”">​</a></h2><p>When something breaks at 2 AM, the person who understands only their own layer points at everyone else. I deliberately keep skills sharp across the whole pipeline — front, back, database, network, deployment — so the buck stops with someone who can actually fix it. Full-stack is not a buzzword here; it is an incident-response strategy.</p><h2 id="_3-security-is-a-habit-not-a-feature" tabindex="-1">3. Security is a habit, not a feature <a class="header-anchor" href="#_3-security-is-a-habit-not-a-feature" aria-label="Permalink to “3. Security is a habit, not a feature”">​</a></h2><p>I write offensive tooling — scanners, analyzers, exploit research — so that defensive thinking is never theoretical. Every panel ships with token + 2FA admin access, every API bridge with account isolation, every deployment with the minimum surface I can manage. Agents make this even more important: machine-written code must be audited by a human who knows what attacks look like.</p><h2 id="_4-write-it-down" tabindex="-1">4. Write it down <a class="header-anchor" href="#_4-write-it-down" aria-label="Permalink to “4. Write it down”">​</a></h2><p>A README is a promise. I document setup, architecture decisions and limitations honestly — including the things that do not work yet. The <a href="https://github.com/Godde3s/fa-guides" target="_blank" rel="noreferrer">Persian guides</a> I publish exist because good documentation in your own language can be the difference between learning and giving up.</p><h2 id="_5-improve-other-people-s-work-with-credit" tabindex="-1">5. Improve other people&#39;s work, with credit <a class="header-anchor" href="#_5-improve-other-people-s-work-with-credit" aria-label="Permalink to “5. Improve other people&#39;s work, with credit”">​</a></h2><p>Standing on giants is how software evolves. When I fork or extend someone&#39;s project, I study it first, improve it meaningfully, and credit loudly. That is how I treat the open-source I build on, and how I expect my own work to be treated.</p><div class="tip custom-block"><p class="custom-block-title">The meta-principle</p><p>Ship small, ship honest, ship again. Momentum beats perfection — but honesty about the current state is never negotiable.</p></div>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};